# Generated by build.py from recipe.yml for recipe imap-search-by-sender-and-date. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'mail1.eml'), "From: shop@example.com`nTo: ann@example.com`nDate: Mon, 02 Mar 2026 10:00:00 +0000`nSubject: Order 1`n`nFirst.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'mail2.eml'), "From: bank@example.org`nTo: ann@example.com`nDate: Wed, 15 Apr 2026 10:00:00 +0000`nSubject: Statement`n`nYour statement.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'mail3.eml'), "From: shop@example.com`nTo: ann@example.com`nDate: Fri, 10 Jul 2026 10:00:00 +0000`nSubject: Order 2`n`nSecond.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'mail4.eml'), "From: Shop Team <shop@example.com>`nTo: ann@example.com`nDate: Tue, 03 Nov 2026 10:00:00 +0000`nSubject: Order 3`n`nThird.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u ann@example.com:annpass --mail-from sender@example.org --mail-rcpt ann@example.com -T "mail[1-4].eml" smtp://127.0.0.1:8080/example.org
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 4 FLAGS" imap://127.0.0.1:8081/INBOX
try { curl.exe -s -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?FROM%20shop%20SENTSINCE%2001-Jun-2026" --next -s -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=[3-4];SECTION=HEADER.FIELDS%20(FROM%20SUBJECT)" } finally { Stop-Process $server0 }
